// QA (plans/release-plan-mcp-server.md, Phase 4): boards stored through the MCP tools are the
// server validator's normalized output (`app/services/plan_board.validate_board`). The client must
// treat them as already normalized, and Sync from ADO must find the stored connection.
// Fixture: src/server/tests/fixtures/mcp_board_normalized.json (generated by `validate_board`;
// the server test `test_mcp_integration.py` asserts it is still `validate_board`'s fixed point).
import { describe, expect, it } from "vitest";
import fixture from "../../../../server/tests/fixtures/mcp_board_normalized.json";
import { sequentialIds } from "../../test/releasePlanFixtures";
import { planConnection } from "./selectors";
import { NO_EPIC_ID } from "./types";
import { normalizePlan } from "./validate";

const boards = { releases: fixture.releases, sprints: fixture.sprints };

describe("MCP-created boards (server fixture)", () => {
  it("covers both modes, flags and the no-epic Epic", () => {
    expect(fixture.releases.mode).toBe("releases");
    expect(fixture.sprints.mode).toBe("sprints");
    expect(fixture.sprints.flags.length).toBeGreaterThan(0);
    for (const board of Object.values(boards)) {
      expect(board.epics.at(-1)?.id).toBe(NO_EPIC_ID);
    }
  });

  it.each(Object.entries(boards))("normalizePlan(%s board) deep-equals the fixture", (_mode, board) => {
    const input = JSON.parse(JSON.stringify(board)); // as it arrives from GET /api/plan/{id}
    expect(normalizePlan(input, sequentialIds())).toEqual(board);
    expect(input).toEqual(board); // not mutated
  });

  it.each(Object.entries(boards))("planConnection(source) is non-null for the %s board, so Sync from ADO works", (_mode, board) => {
    const plan = normalizePlan(JSON.parse(JSON.stringify(board)), sequentialIds());
    const connection = planConnection(plan.source);
    expect(connection).not.toBeNull();
    expect(connection).toEqual({
      source: board.source.kind,
      projectUrl: board.source.projectUrl,
      scopeType: board.source.scopeType,
      scopePath: board.source.scopePath,
    });
  });
});
